1	/**
2	 * Gradium voice for BrickBuddy: streaming text-to-speech and tap-to-talk speech-to-text.
3	 * The browser only ever holds a single-use token minted by our backend, never the API key.
4	 */
5	import { post } from './api';
6	import type { VoiceAdapter } from './agent';
7	
8	/** End of turn: Gradium's 2 s-horizon inactivity probability must stay above the threshold this many steps (80 ms each) in a row. */
9	export const VAD_THRESHOLD = 0.6;
10	export const VAD_CONSECUTIVE_STEPS = 4;
11	/** Hard cap on one utterance. */
12	export const MAX_LISTEN_MS = 30000;
13	
14	const TTS_URL = 'wss://api.gradium.ai/api/speech/tts';
15	const STT_URL = 'wss://api.gradium.ai/api/speech/asr';
16	const TTS_RATE = 48000; // output_format "pcm": 48 kHz, 16-bit, mono
17	const STT_RATE = 24000; // input_format "pcm": 24 kHz, 16-bit, mono
18	const CHUNK_SAMPLES = 1920; // 80 ms at 24 kHz
19	const SCHEDULE_AHEAD_S = 0.06;
20	const FLUSH_TIMEOUT_MS = 2500; // how long to wait for the last words after end_of_stream
21	const MAX_BACKLOG_CHUNKS = 50; // audio captured while the token and socket are still on their way (4 s)
22	
23	/** Gradium cannot be used at all (not configured, token rejected, unreachable): callers should fall back. */
24	export class VoiceUnavailable extends Error {
25	  constructor(message = 'Voice is not available right now.') { super(message); this.name = 'VoiceUnavailable'; }
26	}
27	
28	interface VoiceToken { token: string; voice_id: string; }
29	interface TtsMessage { type?: string; audio?: string; sample_rate?: number; message?: string; }
30	interface SttMessage { type?: string; text?: string; message?: string; vad?: { inactivity_prob?: number }[]; }
31	
32	/** One single-use token per WebSocket connection. It expires within seconds: mint it right before connecting, never cache it. */
33	async function getToken(): Promise<VoiceToken> {
34	  try {
35	    const body = await post<VoiceToken>('/voice/token');
36	    if (typeof body?.token !== 'string' || !body.token) throw new Error('The voice service returned no token.');
37	    return body;
38	  } catch (error) {
39	    throw new VoiceUnavailable(error instanceof Error ? error.message : undefined);
40	  }
41	}
42	const openSocket = (url: string, token: string) => new WebSocket(`${url}?token=${encodeURIComponent(token)}`);
43	function send(socket: WebSocket | null, message: object) {
44	  if (socket?.readyState === WebSocket.OPEN) socket.send(JSON.stringify(message));
45	}
