  const track = stream.getAudioTracks()[0];
  out.track = {label: track.label, muted: track.muted, enabled: track.enabled, state: track.readyState, settings: track.getSettings()};
  const ctx = new AudioContext(); out.ctxStateAtStart = ctx.state; out.sampleRate = ctx.sampleRate;
  await Promise.race([ctx.resume(), new Promise(r => setTimeout(r, 1000))]); out.ctxStateAfterResume = ctx.state;
  const an = ctx.createAnalyser(); an.fftSize = 2048; ctx.createMediaStreamSource(stream).connect(an);
  const buf = new Float32Array(2048); let peak = 0; const t0 = ctx.currentTime;
